(function (HQ) { 'use strict';
const S=HQ.S;
const {splitChain,D,K,appOf,live,insideBox,FILES,newDep,portUsed,tick,MSG0,PICS}=HQ;
/* ---------- missions ---------- */
const NL=s=>s.trim().replace(/\s+/g,' ');
const has=(c,re)=>re.test(NL(c.line));
const hasCmd=(c,re)=>splitChain(NL(c.line)).some(x=>re.test(x.cmd.trim().replace(/^sudo\s+/,'')));
const C=n=>D().containers.find(x=>x.name===n);
const Crun=n=>{const x=C(n);return !!x&&x.status==='running'};
const Dep=(n,ns='default')=>K().deps[ns+'/'+n];
const Pods=(app,ns='default')=>K().pods.filter(p=>p.ns===ns&&appOf(p)===app&&live(p));
const Img=k=>!!D().images[k];
const inside=()=>insideBox();
function ensureFiles(names){let n=0;for(const f of names)if(S.files[f]==null){S.files[f]=FILES[f];n++}return n}
function ensureWebDep(img){let d=Dep('web');if(!d){newDep({name:'web',ns:'default',replicas:3,image:img||'nginx:1.26',cname:'nginx'});return 1}return 0}
/* pre() returns commands, or thunks yielding one, that create only what the mission is missing */
const WEB=()=>Crun('web')?[]:[C('web')?'docker start web':'docker run -d --name web nginx'];
const IN_WEB=()=>[...WEB(),...(inside()?.name==='web'?[]:['docker exec -it web sh'])];
const PORT8080=()=>portUsed(8080)?[]:C('web')?.ports.some(p=>p[0]===8080)?['docker start web']:[`docker run -d --name ${C('web')?'web-8080':'web'} -p 8080:80 nginx`];
const NET=()=>D().networks.shopnet?[]:['docker network create shopnet'];
const CACHE=()=>[...NET(),...(Crun('cache')?[]:[C('cache')?'docker start cache':'docker run -d --name cache --network shopnet redis'])];
const DECKHAND=()=>inside()?.name==='deckhand'?[]:C('deckhand')?[...(Crun('deckhand')?[]:['docker start deckhand']),'docker exec -it deckhand sh']:['docker run -it --name deckhand alpine sh'];
const VOL_BOX=()=>inside()?.mounts?.some(m=>m.vol==='logbook'&&m.path==='/data')?[]:['docker run -it --rm -v logbook:/data alpine sh'];
const NOTE=()=>D().volumes.logbook?.files['note.txt']!=null?[]:['docker run -it --rm -v logbook:/data alpine sh','echo "I survive" > /data/note.txt','exit'];
const BUILD=tag=>Img('shop:'+tag)?[]:[`docker build -t shop:${tag} .`];
const SHOP=()=>[...BUILD('1.0'),...(Crun('shop')?[]:[C('shop')?'docker start shop':'docker run -d --name shop -p 3000:3000 shop:1.0'])];
const UP=()=>Crun('shop-web-1')&&Crun('shop-cache-1')?[]:['docker compose up -d'];
const WEBDEP=()=>Dep('web')?[]:['kubectl create deployment web --image=nginx:1.26 --replicas=3'];
const SVC=()=>K().svcs['default/web']?[]:['kubectl expose deployment web --port=80 --type=NodePort'];
// pods take ~90 simulated seconds to settle (port-forward refuses a pod that is not Running)
const SETTLE=()=>{for(let i=0;i<3;i++){HQ.skewBy(30000);tick()}return ''};
const FWD=()=>K().fwd[9090]?[]:[SETTLE,'kubectl port-forward svc/web 9090:80'];
const BAD_ROLLOUT=()=>{const i=Dep('web')?.image;return i==='nginx:1.99'?[]:[...WEBDEP(),...(i==='nginx:1.27'?[]:['kubectl set image deployment/web nginx=nginx:1.27']),'kubectl set image deployment/web nginx=nginx:1.99']};
const NS=()=>K().nss.shop?[]:['kubectl create namespace shop'];
const SHOP_APPLIED=()=>[...NS(),...(Dep('shop','shop')?[]:['kubectl apply -f shop.yaml'])];
const CH=[
{name:'Hello, Docker',tier:'beginner',group:'Docker',badge:'Crate Note',story:'A tiny hello crate lands at the arrivals dock with a note on it; check the dock is awake, unpack the crate, and find the note that mentions a chest.',view:'docker',files:['README.md'],learned:['docker version','docker run','docker ps','docker ps -a','docker images'],missions:[
 {t:'Is the dock awake?',i:'Harbormaster Marlow hid her sea chest on the docks, and a tiny crate has landed at the arrivals dock with a note on it. Docker runs as a background service on your computer called the engine. Its job is to run <b>containers</b>: programs running in their own little box, separate from the rest of your computer. The <code>docker</code> command is how you talk to it. First, check that both answer.',g:'Gull squawks that the dock may be asleep, so check that it answers: type <code>docker version</code>',a:[['docker','cmd'],['version','sub']],h:'Exactly as written: docker, a space, version.',ans:'docker version',ok:c=>has(c,/^docker (version|--version|-v)$/),after:'Two parts answered: the Client (the `docker` command you type) and the Server (the engine that runs containers).'},
 {t:'Unpack the hello crate',i:'The tiny hello crate waits on the dock, and its note is inside. <b>hello-world</b> is a tiny program whose only job is to print a message. Programs come packed as <b>images</b> (a program plus everything it needs to run), and <code>docker run</code> starts a container from one. You don\'t have this image yet, so Docker will download it first.',g:'Unpack the crate: run <code>docker run hello-world</code>',a:[['docker','cmd'],['run','sub'],['hello-world','img']],h:'docker run, then the image name: hello-world',ans:'docker run hello-world',ok:c=>hasCmd(c,/^docker (container )?run\b/)&&D().containers.some(x=>x.imgKey==='hello-world:latest'),after:'Read the numbered steps it printed. That is the whole Docker workflow in four lines: client → engine → pull image → run container. (The output says "daemon", which is just another word for the engine. "Pull" means download, and Docker Hub is the public online shelf of images.)'},
 {t:'Is anything still on the dock?',i:'Gull circles the dock to see what is still moving. <code>docker ps</code> lists running containers. Before you look: hello-world printed its message and then stopped. What do you expect to see?',g:'Ask Gull for the dock list: type <code>docker ps</code>',a:[['docker','cmd'],['ps','sub']],h:'ps is short for "process status".',ans:'docker ps',ok:c=>has(c,/^docker (ps|container ls|container list)$/),after:'Empty. A container lives only as long as the program it was started to run. hello-world finished its job, so the container stopped.'},
 {t:'Crates that already left',i:'Marlow keeps a record of every crate that came and left. Stopped containers are not deleted. They wait on disk until you remove them. The <code>-a</code> option means <b>all</b>.',g:'Read Marlow\'s full arrivals record: type <code>docker ps -a</code>',a:[['docker','cmd'],['ps','sub'],['-a','opt']],h:'Add -a after ps.',ans:'docker ps -a',ok:c=>has(c,/^docker (ps|container ls) (-a|--all)$/),after:'There it is, with STATUS "Exited (0)". Exit code 0 means it finished without errors. Docker also gave it a random two-word name.'},
 {t:'The delivery stays on the shelf',i:'Unpacking the crate left its delivery on the dock shelf. The download is kept as an <b>image</b> on your machine. Next time it starts instantly.',g:'Check the shelf: type <code>docker images</code>',a:[['docker','cmd'],['images','sub']],h:'docker images, plural.',ans:'docker images',ok:c=>has(c,/^docker (images|image ls|image list)$/),after:'Look at the size: hello-world is tiny. Most images are tens or hundreds of MB.'},
 {t:'One image, many containers',pre:()=>D().containers.some(x=>x.imgKey==='hello-world:latest')?[]:['docker run hello-world'],i:'Gull drops off a second hello crate. Every <code>docker run</code> creates a brand-new container. Run hello-world again and compare. Watch the live view on the right.',g:'Unpack Gull\'s crate with <code>docker run hello-world</code> once more, then <code>docker ps -a</code>',steps:[
   {g:'Run <code>docker run hello-world</code> once more',a:[['docker','cmd'],['run','sub'],['hello-world','img']],h:'Same command as before. Press ↑ to bring it back.',ans:'docker run hello-world',ok:c=>has(c,/^docker run hello-world$/)&&c.code===0},
   {g:'List them all with <code>docker ps -a</code>',a:[['docker','cmd'],['ps','sub'],['-a','opt']],h:'Add -a after ps.',ans:'docker ps -a',ok:c=>has(c,/^docker (ps|container ls) (-a|--all)$/)}],after:'No "Unable to find image" this time: the image was already here. And now there are two separate containers made from the same image. Gull reads out Marlow\'s note from the first crate: the sea chest waits in the harbor shop.'},
]},
{name:'Images',tier:'beginner',badge:'Cargo Catalog',story:'The supply quay stocks goods by name and version; fetch some, compare them, and find the dock\'s cargo catalog.',view:'docker',learned:['docker pull','name:tag','docker history','docker rmi'],missions:[
 {t:'Order stock from the quay',i:'The supply quay stocks goods by name and version, and the dock\'s cargo catalog sits on its shelf. <code>docker pull</code> fetches an image and stops there. <b>nginx</b> is a popular web server (a program that hands out web pages). Images are built from pieces called layers, one per step used to make the image, and you will see them download one by one.',g:'Order the quay\'s nginx stock: type <code>docker pull nginx</code>',a:[['docker','cmd'],['pull','sub'],['nginx','img']],h:'docker pull nginx',ans:'docker pull nginx',ok:c=>hasCmd(c,/^docker (image )?pull\b/)&&Img('nginx:latest'),after:'"Using default tag: latest". A tag is a version name (more on that next); with none given, Docker picks the one called latest. Each "Pull complete" line was one layer.'},
 {t:'Order a specific version',i:'The quay keeps goods in several versions. A <b>tag</b> follows the colon and usually names a version. Pinning a version means everyone gets exactly the same thing.',g:'Ask for the quay\'s 1.26 shelf: <code>docker pull nginx:1.26</code>',a:[['docker','cmd'],['pull','sub'],['nginx','img'],[':1.26','val']],h:'No spaces around the colon: nginx:1.26',ans:'docker pull nginx:1.26',ok:c=>hasCmd(c,/^docker (image )?pull\b/)&&Img('nginx:1.26'),after:'In real projects, pin a tag. "latest" moves over time, and a surprise upgrade can break things.'},
 {t:'Count the stock on your shelf',pre:()=>['nginx','nginx:1.26'].filter(t=>!Img(t.includes(':')?t:t+':latest')).map(t=>'docker pull '+t),i:'Walk your shelf and list your images. Spot the two nginx rows.',g:'Walk the shelf: type <code>docker images</code>',a:[['docker','cmd'],['images','sub']],h:'docker images',ans:'docker images',ok:c=>has(c,/^docker (images|image ls|image list)$/)&&Img('nginx:latest')&&Img('nginx:1.26'),after:'Same REPOSITORY, different TAG and IMAGE ID: they are different images.'},
 {t:'Peek at a crate\'s layers',i:'Gull peeks into a cargo crate. An image is a stack of read-only layers, one per step used to make the image. <code>docker history</code> shows the stack, newest on top.',g:'Peek inside: type <code>docker history nginx</code>',a:[['docker','cmd'],['history','sub'],['nginx','img']],h:'docker history nginx',ans:'docker history nginx',ok:c=>has(c,/^docker (image )?history \S*nginx/),after:'The bottom layer is a whole Debian Linux. Big layers come from installing software. Lines with 0B only record settings, not files.'},
 {t:'The quay\'s smallest crate',i:'Captain Brine boasts that big crates are for show. <b>alpine</b> is a very small Linux image, popular as a base for other images.',g:'Fetch the smallest crate on the quay: <code>docker pull alpine</code>',a:[['docker','cmd'],['pull','sub'],['alpine','img']],h:'docker pull alpine',ans:'docker pull alpine',ok:c=>hasCmd(c,/^docker (image )?pull\b/)&&Img('alpine:latest'),after:'Run `docker images` and compare sizes: about 8MB for alpine against about 190MB for nginx.'},
 {t:'Clear the shelf',i:'The quay shelf is filling up. Images take disk space. <code>docker rmi</code> removes one (rmi = remove image). Remove the 1.26 one; you will pull it again later.',g:'Clear the old version off the shelf: type <code>docker rmi nginx:1.26</code>',a:[['docker','cmd'],['rmi','sub'],['nginx:1.26','img']],h:'docker rmi nginx:1.26',ans:'docker rmi nginx:1.26',ok:c=>!Img('nginx:1.26')&&has(c,/^docker (rmi|image rm)/),after:'"Untagged" removes the name; "Deleted" frees the layers no other image uses. On the cleared shelf lies the dock\'s cargo catalog.'},
]},
{name:'Containers',tier:'beginner',badge:'Captain\'s Cap',story:'Marlow\'s crew runs a little web stall on deck; start it, look inside, stop it, and find the captain\'s cap.',view:'docker',learned:['docker run -d --name','docker logs','docker exec -it','docker stop','docker start','docker rm -f'],missions:[
 {t:'Open the crew\'s web stall',i:'Marlow\'s crew runs a little web stall on deck, and the captain\'s cap is somewhere near it. A web server is meant to keep running. <code>-d</code> (detached) starts it in the background and gives your prompt back. <code>--name</code> gives it a name you choose.',g:'Open the stall on deck, named web: type <code>docker run -d --name web nginx</code>',a:[['docker','cmd'],['run','sub'],['-d','opt'],['--name web','opt'],['nginx','img']],h:'Options go before the image name.',ans:'docker run -d --name web nginx',ok:c=>hasCmd(c,/^docker (container )?run\b/)&&Crun('web'),after:'The long code it printed is the container ID. Look at the live view: web is running (green light).'},
 {t:'Is the stall open?',pre:()=>WEB(),i:'Gull flies over the deck to see who is open: list running containers again. A port is a numbered door on a program, and web servers wait at door 80: <code>80/tcp</code> in the PORTS column is door 80 over tcp, the kind of connection web traffic uses.',g:'Ask Gull for the deck list: type <code>docker ps</code>',a:[['docker','cmd'],['ps','sub']],h:'docker ps',ans:'docker ps',ok:c=>has(c,/^docker (ps|container ls)/)&&Crun('web'),after:'STATUS says "Up …" and PORTS says 80/tcp: nginx listens on port 80, but only inside the container for now.'},
 {t:'Read the stall\'s diary',i:'Marlow asks what the stall has been up to. Whatever the program inside prints goes to the container\'s log. This is your first stop when something goes wrong.',g:'Read the diary: type <code>docker logs web</code>',a:[['docker','cmd'],['logs','sub'],['web','arg']],h:'docker logs, then the container name.',ans:'docker logs web',ok:c=>has(c,/^docker (container )?logs (-f )?web$/),after:'nginx reported it is ready. In a real terminal, `docker logs -f` keeps following new lines.'},
 {t:'Step behind the counter',pre:()=>WEB(),i:'Marlow waves you behind the stall\'s counter. <code>docker exec</code> runs a command inside a running container. A <b>shell</b> is a text prompt where you type commands, and <code>sh</code> is the simplest one. With <code>-it</code> and <code>sh</code> you get a shell in there: <code>-i</code> keeps your keyboard connected to the container and <code>-t</code> gives it a terminal, and a shell needs both to talk back to you.',g:'Go behind the counter: type <code>docker exec -it web sh</code>',a:[['docker','cmd'],['exec','sub'],['-it','opt'],['web','arg'],['sh','arg']],h:'-i keeps input open, -t gives you a terminal. Together: -it',ans:'docker exec -it web sh',ok:c=>{const b=inside();return !!b&&b.name==='web'&&hasCmd(c,/^docker (container )?exec\b/)},after:'Your prompt changed. You are now in the container\'s own files, as root (the all-powerful admin user). Your laptop\'s files are not here.'},
 {t:'Find the stall\'s sign',pre:()=>IN_WEB(),i:'The stall\'s front page hangs on its back wall like a sign. nginx serves files from <code>/usr/share/nginx/html</code>. <code>cat</code> prints a file\'s text, so use it to look at the default page from inside.',g:'Read the sign: type <code>cat /usr/share/nginx/html/index.html</code>',a:[['cat','cmd'],['/usr/share/nginx/html/index.html','arg']],h:'Use Tab to complete the path piece by piece.',ans:'cat /usr/share/nginx/html/index.html',ok:c=>{const b=inside();return !!b&&has(c,/^cat \S*index\.html$/)},after:'That is the page nginx sends to visitors. Try `ls /` too: `ls` lists the files in a folder, and `/` is the top one.'},
 {t:'Step back out on deck',pre:()=>IN_WEB(),i:'The deck bell rings. Leave the container shell. Because you came in with exec, the container keeps running.',g:'Leave the stall: type <code>exit</code>',a:[['exit','cmd']],h:'Type exit.',ans:'exit',ok:c=>!S.inside&&has(c,/^exit$/)&&Crun('web'),after:'Back on your laptop, and web is still up.'},
 {t:'Close the stall for the night',pre:()=>WEB(),i:'Night falls on the deck. <code>docker stop</code> asks the program inside to shut down politely.',g:'Close the stall: type <code>docker stop web</code>',a:[['docker','cmd'],['stop','sub'],['web','arg']],h:'docker stop web',ans:'docker stop web',ok:c=>{const x=C('web');return !!x&&x.status==='exited'&&hasCmd(c,/^docker (container )?(stop|kill)\b/)},after:'The light went grey. The container still exists; `docker ps -a` would show it as Exited.'},
 {t:'Reopen the stall at dawn',pre:()=>C('web')?[]:['docker run -d --name web nginx','docker stop web'],i:'Dawn comes and the crew wants the stall back. A stopped container can be started again with the same settings and name.',g:'Reopen it: type <code>docker start web</code>',a:[['docker','cmd'],['start','sub'],['web','arg']],h:'docker start web',ans:'docker start web',ok:c=>Crun('web')&&has(c,/^docker (container )?(start|restart) web/),after:'Up again. start reuses the existing container; run would make a new one.'},
 {t:'Take the stall down',i:'Captain Brine wants the deck cleared. <code>docker rm</code> deletes a container. It refuses while it is running unless you add <code>-f</code> (force), which stops it first.',g:'Clear the deck: type <code>docker rm -f web</code>',a:[['docker','cmd'],['rm','sub'],['-f','opt'],['web','arg']],h:'docker rm -f web',ans:'docker rm -f web',ok:c=>!C('web')&&hasCmd(c,/^docker (container )?rm\b/),after:'Gone, along with anything that was changed inside it. The nginx image is still here, ready for the next container. Where the stall stood, the captain\'s cap lies on the planks.'},
]},
{name:'Ports & networks',tier:'beginner',badge:'Signal Whistle',story:'Visitors need a numbered door and a private lane between stalls; open doors, call a neighbor by name, and find the signal whistle.',view:'docker',learned:['-p HOST:CONTAINER','curl localhost:PORT','docker network create','--network','container names as hostnames'],missions:[
 {t:'Open a numbered door',i:'Visitors need a numbered door to reach the stall, and stalls need a private lane to call each other; the signal whistle hangs by the doors. A container\'s ports are private. <code>-p 8080:80</code> connects port 8080 on your laptop to port 80 inside the container. Read it as <b>laptop : container</b>.',g:'Give the stall its numbered door: type <code>docker run -d --name web -p 8080:80 nginx</code>',a:[['docker','cmd'],['run','sub'],['-d','opt'],['--name web','opt'],['-p 8080:80','opt'],['nginx','img']],h:'If the name web is taken, remove the old one first: docker rm -f web',ans:'docker run -d --name web -p 8080:80 nginx',ok:c=>{const x=C('web');return !!x&&x.status==='running'&&x.ports.some(p=>p[0]===8080&&p[1]===80)&&hasCmd(c,/^docker (container )?run\b/)},after:'The live view shows the published port on the card: 8080 → 80.'},
 {t:'Knock on the stall\'s door',pre:()=>PORT8080(),i:'A visitor walks up to door 8080. <code>curl</code> fetches a web page in the terminal, like a browser without the pictures. <code>localhost</code> means "this computer", so <code>localhost:8080</code> is port 8080 on your laptop.',g:'Knock on the door: type <code>curl localhost:8080</code>',a:[['curl','cmd'],['localhost:8080','arg']],h:'curl localhost:8080',ans:'curl localhost:8080',ok:c=>has(c,/^curl (http:\/\/)?(localhost|127\.0\.0\.1):8080\/?$/)&&c.code===0,after:'That HTML came from nginx inside the container. On a real machine you could open http://localhost:8080 in your browser too.'},
 {t:'A second server',i:'Gull spots room for a second stall next door. Run a different web server, Apache (<b>httpd</b>), next to it. It also listens on port 80 inside its own container. That is fine: each container has its own ports.',g:'Open the second stall: type <code>docker run -d --name web2 -p 8081:80 httpd</code>, then curl port 8081',steps:[
   {g:'Type <code>docker run -d --name web2 -p 8081:80 httpd</code>',a:[['docker','cmd'],['run','sub'],['-d','opt'],['--name web2','opt'],['-p 8081:80','opt'],['httpd','img']],h:'Same shape as before, with a new name, a new laptop port, and the httpd image.',ans:'docker run -d --name web2 -p 8081:80 httpd',ok:c=>has(c,/^docker run\b.*--name web2\b/)&&Crun('web2')&&C('web2').ports.some(p=>p[0]===8081)},
   {g:'Ask it for a page with <code>curl localhost:8081</code>',a:[['curl','cmd'],['localhost:8081','arg']],h:'curl localhost:8081',ans:'curl localhost:8081',ok:c=>has(c,/^curl\b.*:8081\b/)&&c.code===0}],after:'Two servers, both on port 80 inside, reachable on 8080 and 8081 outside.'},
 {t:'Two stalls, one door',pre:()=>PORT8080(),i:'Captain Brine tries to squeeze in at door 8080. Only one thing on your laptop can hold a port. Try to give a third server port 8080 and read the error.',g:'Let Brine try door 8080 too: type <code>docker run -d --name web3 -p 8080:80 nginx</code>',a:[['docker','cmd'],['run','sub'],['-p 8080:80','opt'],['nginx','img']],h:'Use the same -p 8080:80 again on purpose.',ans:'docker run -d --name web3 -p 8080:80 nginx',ok:c=>hasCmd(c,/^docker (container )?run\b/)&&/port is already allocated/.test(c.out),after:'"port is already allocated". web3 was created but could not start (check `docker ps -a`). Clean up with `docker rm` web3 when you like.'},
 {t:'Lay a private lane',i:'Stalls need a private lane to call each other. Containers you put on a network that <b>you</b> created can find each other by name. Create one for the shop.',g:'Lay the lane: type <code>docker network create shopnet</code>',a:[['docker','cmd'],['network','sub'],['create','sub'],['shopnet','arg']],h:'docker network create shopnet',ans:'docker network create shopnet',ok:c=>hasCmd(c,/^docker network create\b/)&&!!D().networks.shopnet,after:'`docker network ls` lists it next to the built-in ones. The one called bridge is the default network every container joins unless you say otherwise; host and none are special cases you can ignore for now.'},
 {t:'Station a cache on the lane',pre:()=>NET(),i:'The lane\'s first guest is <b>redis</b>, a fast little database. Start it on shopnet with the name <b>cache</b>. No <code>-p</code> needed: only other containers will talk to it.',g:'Move the cache onto the lane: type <code>docker run -d --name cache --network shopnet redis</code>',a:[['docker','cmd'],['run','sub'],['-d','opt'],['--name cache','opt'],['--network shopnet','opt'],['redis','img']],h:'--network goes before the image name, like every option.',ans:'docker run -d --name cache --network shopnet redis',ok:c=>{const x=C('cache');return !!x&&x.status==='running'&&x.net==='shopnet'&&hasCmd(c,/^docker (container )?run\b/)},after:'cache got an IP address on shopnet (its number on the network, a bit like a phone number). A hostname is a name that stands for such a number, and cache\'s name now works as one on that network.'},
 {t:'Call the cache by name',pre:()=>CACHE(),i:'Gull flies a message down the lane. Start a throwaway alpine on the same network and ping <b>cache</b> by name. <code>ping</code> sends a few tiny test messages to a name and waits for replies; <code>-c 3</code> means "send 3". <code>--rm</code> deletes the container as soon as it exits.',g:'Send Gull to the cache: type <code>docker run --rm --network shopnet alpine ping -c 3 cache</code>',a:[['docker','cmd'],['run','sub'],['--rm','opt'],['--network shopnet','opt'],['alpine','img'],['ping -c 3 cache','arg']],h:'Everything after the image name is the command to run inside the container.',ans:'docker run --rm --network shopnet alpine ping -c 3 cache',ok:c=>/ping/.test(c.line)&&/cache/.test(c.line)&&/packets received/.test(c.out),after:'The name "cache" turned into an IP. Docker runs a small DNS server for every network you create (DNS is the phone book that turns names into IP addresses).'},
 {t:'Call across the open quay',i:'Brine\'s stall is off the lane. Try the same thing on the default network to see the difference.',g:'Try it from outside the lane: type <code>docker run --rm alpine ping -c 1 cache</code>',a:[['docker','cmd'],['run','sub'],['--rm','opt'],['alpine','img'],['ping -c 1 cache','arg']],h:'Leave out --network this time.',ans:'docker run --rm alpine ping -c 1 cache',ok:c=>hasCmd(c,/^docker (container )?run\b/)&&/bad address 'cache'|Name or service not known/.test(c.out),after:'"bad address". The default bridge network has no names. Lesson: create a network for containers that need to talk. Hanging by the tower door is the signal whistle.'},
]},
{name:'Volumes & settings',tier:'beginner',badge:'Ship\'s Ledger',story:'Whatever the stall writes is lost when it leaves; keep a logbook that survives and feed a crashed stall its missing setting, and find the ship\'s ledger.',view:'docker',learned:['docker volume create','-v NAME:/path','--rm','-e KEY=value','docker logs for crashes'],missions:[
 {t:'Hire a deckhand',i:'Whatever the stall writes is lost when it leaves, so Marlow wants a logbook that survives. Start an alpine shell called <b>deckhand</b>. With <code>-it</code> and no <code>-d</code>, you land straight inside.',g:'Hire a deckhand for the office: type <code>docker run -it --name deckhand alpine sh</code>',a:[['docker','cmd'],['run','sub'],['-it','opt'],['--name deckhand','opt'],['alpine','img'],['sh','arg']],h:'docker run -it --name deckhand alpine sh',ans:'docker run -it --name deckhand alpine sh',ok:c=>{const b=inside();return !!b&&b.name==='deckhand'&&hasCmd(c,/^docker (container )?run\b/)},after:'This shell is the program the container was started to run. When you exit it, the container stops.'},
 {t:'Save a note',pre:()=>DECKHAND(),i:'The deckhand scribbles in the margin. Write a file inside the container. <code>echo</code> prints the text you give it, and <code>&gt;</code> sends that text into a file instead of the screen.',g:'Scribble the margin note: type <code>echo "remember me" &gt; /note.txt</code>, then <code>cat /note.txt</code>',steps:[
   {g:'Type <code>echo "remember me" &gt; /note.txt</code>',a:[['echo','cmd'],['"remember me"','arg'],['>','op'],['/note.txt','arg']],h:'echo "remember me" > /note.txt',ans:'echo "remember me" > /note.txt',ok:c=>{const b=inside();return !!b&&b.name==='deckhand'&&b.fs['/note.txt']!=null&&has(c,/^echo\b.*>>? ?\/note\.txt$/)}},
   {g:'Read it back with <code>cat /note.txt</code>',a:[['cat','cmd'],['/note.txt','arg']],h:'cat /note.txt',ans:'cat /note.txt',ok:c=>{const b=inside();return !!b&&b.name==='deckhand'&&b.fs['/note.txt']!=null&&has(c,/^cat \/note\.txt$/)}}],after:'The note lives in the container\'s own writable layer, a thin scratch space on top of the read-only image layers.'},
 {t:'Dismiss the deckhand',i:'Captain Brine dismisses the deckhand. Leave, then delete the container. What happens to the note? On one line, <code>&amp;&amp;</code> means "and then, but only if the first command worked", so the second command never runs after a failure.',g:'Send the deckhand off: type <code>exit</code>, then <code>docker rm deckhand</code>',a:[['exit','cmd'],['&&','op'],['docker rm deckhand','cmd']],h:'You can do both in one line: exit, then on your laptop docker rm deckhand. In a line like that, && means "and then, if that worked".',ans:()=>S.inside?'exit':'docker rm deckhand',ok:c=>!S.inside&&!C('deckhand')&&hasCmd(c,/^docker (container )?rm\b/),after:'The note is gone with it. A container\'s own files are disposable.'},
 {t:'Open the logbook',i:'Marlow opens a proper logbook. A <b>volume</b> is storage that Docker keeps outside any container.',g:'Start the logbook: type <code>docker volume create logbook</code>',a:[['docker','cmd'],['volume','sub'],['create','sub'],['logbook','arg']],h:'docker volume create logbook',ans:'docker volume create logbook',ok:c=>hasCmd(c,/^docker volume create\b/)&&!!D().volumes.logbook,after:'It shows up in the live view as a drum. It is empty for now. `docker volume ls` lists your volumes.'},
 {t:'Shelve the logbook in the office',i:'The office wants the logbook within reach. <code>-v logbook:/data</code> plugs the volume in at the folder /data inside the container. <code>--rm</code> removes the container when you exit.',g:'Plug in the logbook: type <code>docker run -it --rm -v logbook:/data alpine sh</code>',a:[['docker','cmd'],['run','sub'],['-it','opt'],['--rm','opt'],['-v logbook:/data','opt'],['alpine','img'],['sh','arg']],h:'-v VOLUME:/path/inside',ans:'docker run -it --rm -v logbook:/data alpine sh',ok:c=>{const b=inside();return !!b&&!b.isPod&&b.mounts.some(m=>m.vol==='logbook'&&m.path==='/data')&&hasCmd(c,/^docker (container )?run\b/)},after:'Anything written under /data now goes into the logbook volume.'},
 {t:'Write in the logbook',pre:()=>VOL_BOX(),i:'Make the entry in the logbook, under /data this time.',g:'Make the entry: type <code>echo "I survive" &gt; /data/note.txt</code>',a:[['echo','cmd'],['"I survive"','arg'],['>','op'],['/data/note.txt','arg']],h:'Same as before, with /data/ in front of the file name.',ans:'echo "I survive" > /data/note.txt',ok:c=>hasCmd(c,/^(echo|printf)\b.*>|^tee\b/)&&!!(D().volumes.logbook&&D().volumes.logbook.files['note.txt']!=null),after:'The volume in the live view now holds 1 file.'},
 {t:'Reopen the logbook with a new crew',pre:()=>NOTE(),i:'Brine swears the entry vanished. Exit (the container is deleted thanks to <code>--rm</code>). Then read the note from a brand-new container.',g:'Prove Brine wrong: type <code>exit</code>, then <code>docker run --rm -v logbook:/data alpine cat /data/note.txt</code>',a:[['docker','cmd'],['run','sub'],['--rm','opt'],['-v logbook:/data','opt'],['alpine','img'],['cat /data/note.txt','arg']],h:'After exit, run the cat command in a new container with the same -v.',ans:()=>S.inside?'exit':'docker run --rm -v logbook:/data alpine cat /data/note.txt',ok:c=>!S.inside&&hasCmd(c,/^docker (container )?run\b/)&&/I survive/.test(c.out),after:'Different container, same data. This is how databases keep their data in Docker.'},
 {t:'A container that crashes',i:'Gull brings a database stall that keeps quitting. Some images need settings before they will start. Run the <b>postgres</b> database without any, and see what happens.',g:'Try to open it: type <code>docker run -d --name db postgres</code>, then <code>docker ps -a</code>',steps:[
   {g:'Type <code>docker run -d --name db postgres</code>',a:[['docker','cmd'],['run','sub'],['-d','opt'],['--name db','opt'],['postgres','img']],h:'docker run -d --name db postgres',ans:'docker run -d --name db postgres',ok:c=>{const x=C('db');return has(c,/^docker run\b/)&&!!x&&x.status==='exited'&&x.code===1}},
   {g:'See what happened with <code>docker ps -a</code>',a:[['docker','cmd'],['ps','sub'],['-a','opt']],h:'Add -a after ps, because the container is no longer running.',ans:'docker ps -a',ok:c=>has(c,/^docker (ps|container ls) (-a|--all)$/)}],after:'It printed an ID, so it seemed fine, but it exited with code 1 right away (any code other than 0 means something went wrong). Time to find out why.'},
 {t:'Read the quitting stall\'s diary',i:'Gull wants to know why the stall quit. When a container dies, its logs usually say why.',g:'Read its diary: type <code>docker logs db</code>',a:[['docker','cmd'],['logs','sub'],['db','arg']],h:'docker logs db',ans:'docker logs db',ok:c=>has(c,/^docker (container )?logs db$/),after:'It needs POSTGRES_PASSWORD. Settings like that are passed as environment variables: named settings handed to a program when it starts.'},
 {t:'Hand it the missing setting',pre:()=>C('db')?[]:['docker run -d --name db postgres'],i:'The stall opens once it has its password. <code>-e KEY=value</code> sets an environment variable inside the container. Remove the broken one and start again with a password.',g:'Fix it: type <code>docker rm db &amp;&amp; docker run -d --name db -e POSTGRES_PASSWORD=secret postgres</code>',a:[['docker rm db','cmd'],['&&','op'],['docker run -d --name db','cmd'],['-e POSTGRES_PASSWORD=secret','opt'],['postgres','img']],h:'&& runs the second command only if the first one worked.',ans:'docker rm db && docker run -d --name db -e POSTGRES_PASSWORD=secret postgres',ok:c=>hasCmd(c,/^docker (container )?run\b/)&&Crun('db')&&C('db').env.POSTGRES_PASSWORD,after:'Running. Check `docker logs` db again: "ready to accept connections". In the office drawer lies the ship\'s ledger.'},
]},
{name:'Build an image',tier:'beginner',badge:'Shipwright\'s Mallet',story:'The shipyard builds the harbor shop\'s own crate from a recipe; build version 1, change the message, build version 2, and find the shipwright\'s mallet.',view:'docker',files:['Dockerfile','app.js','package.json','message.txt'],learned:['Dockerfile','docker build -t name:tag .','build cache','docker history','shipping a new version'],missions:[
 {t:'Look over the shipyard bench',i:'The shipyard builds the harbor shop\'s own crate from a recipe, and the shipwright\'s mallet lies on its bench. New files appeared in your folder: a small web app (written for Node.js, a tool that runs JavaScript programs) and a <b>Dockerfile</b>, the recipe for packaging it. <code>ls</code> lists the files in the current folder.',g:'Look over the bench: type <code>ls</code>',a:[['ls','cmd']],h:'Type ls.',ans:'ls',ok:c=>has(c,/^ls( -l| -la| -al)?$/),after:'`app.js` is the program, `package.json` lists its libraries (code written by other people), `message.txt` is what it says, and Dockerfile packages it all.'},
 {t:'Read the shipwright\'s recipe',i:'The shipwright left the recipe on the bench. Each line of a Dockerfile is an instruction. <code>FROM</code> picks the image to build on, <code>RUN</code> happens once while building, and <code>CMD</code> runs each time a container starts. Read the comments: they explain each step.',g:'Read it: type <code>cat Dockerfile</code>',a:[['cat','cmd'],['Dockerfile','arg']],h:'cat Dockerfile (capital D)',ans:'cat Dockerfile',ok:c=>has(c,/^cat Dockerfile$/),after:'FROM picks a base, WORKDIR sets the folder, COPY brings files in, RUN executes a step, EXPOSE documents a port, CMD says what runs at start.'},
 {t:'Build the shop\'s crate, version 1',i:'The shipyard is ready to build. <code>docker build</code> follows the recipe and produces an image. <code>-t</code> gives it a name:tag. The final <code>.</code> means "the files in this folder".',g:'Build version 1 of the shop\'s crate: type <code>docker build -t shop:1.0 .</code>',a:[['docker','cmd'],['build','sub'],['-t shop:1.0','opt'],['.','arg']],h:'Don\'t forget the dot at the end.',ans:'docker build -t shop:1.0 .',ok:c=>hasCmd(c,/^docker (image )?build\b/)&&Img('shop:1.0'),after:'Each [n/5] line was one layer being built. Your image is in the live view now, next to the ones you pulled.'},
 {t:'Inspect the new crate\'s layers',i:'The shipwright shows you what went into the new crate. Your image is a stack too: your layers on top of the node base.',g:'Inspect it: type <code>docker history shop:1.0</code>',a:[['docker','cmd'],['history','sub'],['shop:1.0','img']],h:'docker history shop:1.0',ans:'docker history shop:1.0',ok:c=>has(c,/^docker (image )?history shop:1\.0$/),after:'The top rows are your Dockerfile lines. Below them is everything that came with node:20-alpine.'},
 {t:'Open the harbor shop',pre:()=>BUILD('1.0'),i:'The shop\'s own crate works like any other. The app listens on port 3000.',g:'Open the shop: type <code>docker run -d --name shop -p 3000:3000 shop:1.0</code>',a:[['docker','cmd'],['run','sub'],['-d','opt'],['--name shop','opt'],['-p 3000:3000','opt'],['shop:1.0','img']],h:'Port 3000 outside, 3000 inside.',ans:'docker run -d --name shop -p 3000:3000 shop:1.0',ok:c=>hasCmd(c,/^docker (container )?run\b/)&&Crun('shop')&&C('shop').imgKey==='shop:1.0',after:'It started. The image holds Node.js, the libraries and the code, so this would run the same on any machine with Docker.'},
 {t:'Knock on the shop door',pre:()=>SHOP(),i:'Walk up to the harbor shop and ask for its page.',g:'Knock on the shop door: type <code>curl localhost:3000</code>',a:[['curl','cmd'],['localhost:3000','arg']],h:'curl localhost:3000',ans:'curl localhost:3000',ok:c=>has(c,/^curl (http:\/\/)?localhost:3000\/?$/)&&/Hello from the shop/.test(c.out),after:'That text came from `message.txt`, baked into the image at build time.'},
 {t:'Repaint the shop sign',i:'Marlow wants a new sign over the shop door. Time for version 2. Change what the shop says. You can open the editor with <code>edit FILE</code>, a small editor window (press Save and carry on), or overwrite the file in one line.',g:'Repaint the sign: type <code>edit message.txt</code> and change the text, or <code>echo "Now with fresh pastries!" &gt; message.txt</code>',a:[['echo','cmd'],['"Now with fresh pastries!"','arg'],['>','op'],['message.txt','arg']],h:'Any new text works. Then cat message.txt to check.',ans:'echo "Now with fresh pastries!" > message.txt',ok:c=>hasCmd(c,/^edit message\.txt$|^(echo|printf)\b.*>|^tee\b/)&&S.files['message.txt']!=null&&S.files['message.txt'].trim()!==MSG0,after:'Changing the file does not change the running container. The old text is sealed inside shop:1.0.'},
 {t:'Build the shop\'s version 2',i:'The shipwright builds again, with the new sign. Build again with a new tag. Docker reuses any step whose input has not changed since last time (its <b>cache</b>) and marks it <b>CACHED</b>. Watch which steps say that.',g:'Build version 2: type <code>docker build -t shop:2.0 .</code>',a:[['docker','cmd'],['build','sub'],['-t shop:2.0','opt'],['.','arg']],h:'Same as before with 2.0 as the tag.',ans:'docker build -t shop:2.0 .',ok:c=>hasCmd(c,/^docker (image )?build\b/)&&Img('shop:2.0'),after:'npm install (the step that downloads the libraries) was CACHED because `package.json` did not change. Only the last COPY ran again. That is why the Dockerfile copies `package.json` first.'},
 {t:'Ship it',pre:()=>[...SHOP(),...BUILD('2.0')],i:'Brine gloats over the old sign. Replace the running 1.0 container with a 2.0 one. Containers are not upgraded in place: you swap them.',g:'Swap the shop\'s crate: type <code>docker rm -f shop &amp;&amp; docker run -d --name shop -p 3000:3000 shop:2.0</code>, then curl it',steps:[
   {g:'Type <code>docker rm -f shop &amp;&amp; docker run -d --name shop -p 3000:3000 shop:2.0</code>',a:[['docker rm -f shop','cmd'],['&&','op'],['docker run -d --name shop -p 3000:3000','cmd'],['shop:2.0','img']],h:'Remove, then run with the new tag.',ans:'docker rm -f shop && docker run -d --name shop -p 3000:3000 shop:2.0',ok:c=>has(c,/^(docker rm -f shop && )?docker run\b.*\bshop:2\.0$/)&&Crun('shop')&&C('shop').imgKey==='shop:2.0'},
   {g:'Check the new version with <code>curl localhost:3000</code>',a:[['curl','cmd'],['localhost:3000','arg']],h:'curl localhost:3000',ans:'curl localhost:3000',ok:c=>has(c,/^curl\b.*:3000\b/)&&c.code===0}],after:'curl localhost:3000 shows the new message. Want to go back? Run shop:1.0 again. Both versions still exist. Under the old sign lies the shipwright\'s mallet.'},
]},
{name:'Compose',tier:'beginner',badge:'Conductor\'s Baton',story:'The shop and its database must sail together; start the whole dock with one file, and find the conductor\'s baton.',view:'docker',files:['compose.yaml'],learned:['compose.yaml','docker compose up -d','docker compose ps','docker compose logs','docker compose down'],missions:[
 {t:'The dock schedule',i:'The shop and its database must sail together, and one file can start the whole dock; the conductor\'s baton waits at the end. Typing long <code>docker run</code> commands for every part gets old. <b>Compose</b> describes the app in a file instead (written in YAML, a simple indented text format): the shop and a redis cache to count visits.',g:'Read the dock schedule: type <code>cat compose.yaml</code>',a:[['cat','cmd'],['compose.yaml','arg']],h:'cat compose.yaml',ans:'cat compose.yaml',ok:c=>has(c,/^cat compose\.ya?ml$/),after:'Every `docker run` option has a place in the file: ports, environment, volumes. Indentation matters in YAML.'},
 {t:'Open the whole dock at once',files:['Dockerfile','app.js','package.json','message.txt'],i:'One word from the hall and the whole dock sails. One command builds what is missing, creates a network and volume, and starts both <b>services</b> (the parts of the app: web and cache) in the right order.',g:'Open the dock: type <code>docker compose up -d</code>',a:[['docker','cmd'],['compose','sub'],['up','sub'],['-d','opt']],h:'docker compose up -d',ans:'docker compose up -d',ok:c=>hasCmd(c,/^docker compose up\b/)&&Crun('shop-web-1')&&Crun('shop-cache-1'),after:'Look at the names: project-service-number (the project is the app, here shop). The live view shows the new shop_default network with both on it.'},
 {t:'Who answered the schedule?',i:'Gull counts who showed up. <code>docker compose ps</code> lists only this project\'s containers.',g:'Count the dock: type <code>docker compose ps</code>',a:[['docker','cmd'],['compose','sub'],['ps','sub']],h:'docker compose ps',ans:'docker compose ps',ok:c=>has(c,/^docker compose ps/),after:'The SERVICE column shows the names from the file: web and cache. Those are also their hostnames on the project network.'},
 {t:'Count the shop\'s visitors',files:['Dockerfile','app.js','package.json','message.txt'],pre:()=>UP(),i:'Marlow wants a tally of shop visitors. The shop now talks to redis (REDIS_HOST: cache) and counts visits. It is published on port 4000.',g:'Knock on the shop door: type <code>curl localhost:4000</code> two or three times',a:[['curl','cmd'],['localhost:4000','arg']],h:'Press ↑ and Enter to repeat.',ans:'curl localhost:4000',ok:c=>hasCmd(c,/^curl\b/)&&/Visits: [2-9]|Visits: \d\d/.test(c.out),after:'The counter goes up. web found cache by its service name, just like the ping earlier.'},
 {t:'Read the shop\'s diary',i:'Gull reads out the shop\'s diary: logs from a service, prefixed with its name.',g:'Ask for the diary: type <code>docker compose logs web</code>',a:[['docker','cmd'],['compose','sub'],['logs','sub'],['web','arg']],h:'docker compose logs web',ans:'docker compose logs web',ok:c=>has(c,/^docker compose logs/),after:'Leave out the service name to see every service interleaved.'},
 {t:'Close the dock for the night',files:['Dockerfile','app.js','package.json','message.txt'],pre:()=>UP(),i:'The hall closes at dusk. <code>docker compose down</code> stops and removes the containers and the network. Volumes stay unless you add <code>-v</code>.',g:'Shut the dock: type <code>docker compose down</code>',a:[['docker','cmd'],['compose','sub'],['down','sub']],h:'docker compose down',ans:'docker compose down',ok:c=>hasCmd(c,/^docker compose down\b/)&&!C('shop-web-1')&&!C('shop-cache-1')&&S.flag.composeDown,after:'Containers and network: gone. The cache-data volume is still in the live view.'},
 {t:'Reopen the dock at dawn',files:['Dockerfile','app.js','package.json','message.txt'],pre:()=>S.flag.composeDown?[]:[...UP(),'curl localhost:4000','curl localhost:4000','docker compose down'],i:'Dawn at the hall: start it again and check the tally. Did the visits survive?',g:'Reopen and count: type <code>docker compose up -d &amp;&amp; curl localhost:4000</code>',a:[['docker compose up -d','cmd'],['&&','op'],['curl localhost:4000','cmd']],h:'Up, then curl.',ans:'docker compose up -d && curl localhost:4000',ok:c=>hasCmd(c,/^curl\b/)&&S.flag.composeDown&&/Visits: ([3-9]|\d\d)/.test(c.out),after:'The count picked up where it left off, because redis keeps its data on the volume. New containers, same data. On the hall\'s podium sits the conductor\'s baton.'},
]},
{name:'Meet the cluster',tier:'beginner',group:'Kubernetes',badge:'Cadet\'s Spyglass',story:'Past the harbor lies a whole fleet working together; say hello to it, count its ships, and find the cadet\'s spyglass.',view:'k8s',learned:['kubectl cluster-info','kubectl get nodes','kubectl get pods -A','kubectl run','kubectl describe','kubectl delete pod'],missions:[
 {t:'Hail the fleet',i:'Past the harbor lies a whole fleet working together, and the cadet\'s spyglass is aboard one of its ships. Docker runs containers on one machine. <b>Kubernetes</b> runs them across many machines and keeps them healthy. A group of machines working together is a <b>cluster</b>, and you have a small one called <b>harbor</b>; <code>kubectl</code> is how you talk to it.',g:'Hail the fleet: type <code>kubectl cluster-info</code>',a:[['kubectl','cmd'],['cluster-info','sub']],h:'kubectl cluster-info',ans:'kubectl cluster-info',ok:c=>has(c,/^(kubectl|k) cluster-info$/),after:'The control plane (the cluster\'s brain) answers at an address on port 6443. That is the API server, its front door: `kubectl` only ever talks to it.'},
 {t:'Count the ships',i:'Gull counts the ships on the horizon. Each machine in a cluster is a <b>node</b>. This local cluster fakes three of them with Docker containers.',g:'Count the fleet: type <code>kubectl get nodes</code>',a:[['kubectl','cmd'],['get','sub'],['nodes','arg']],h:'kubectl get nodes',ans:'kubectl get nodes',ok:c=>has(c,/^(kubectl|k) get (nodes|node|no)( -o wide)?$/),after:'One control-plane (the brain) and two workers (where your apps run). All Ready.'},
 {t:'Peek aboard the flagship',i:'Marlow points at the flagship that steers the fleet. A <b>pod</b> is Kubernetes\' wrapper around a container (you will start one in a moment). The cluster\'s own parts run as pods too, kept in a separate area called a <b>namespace</b>, here <b>kube-system</b>. <code>-A</code> shows the pods of every namespace.',g:'Look aboard the whole fleet: type <code>kubectl get pods -A</code>',a:[['kubectl','cmd'],['get','sub'],['pods','arg'],['-A','opt']],h:'-A is short for --all-namespaces',ans:'kubectl get pods -A',ok:c=>has(c,/^(kubectl|k) get (pods|pod|po) (-A|--all-namespaces)/),after:'etcd (its notebook), kube-apiserver (its front door), kube-scheduler (picks a machine for each pod) and kube-controller-manager (keeps things as asked) make up the control plane. coredns is the cluster\'s name service, like the DNS you met with Docker networks.'},
 {t:'Send out your own crew',i:'Time to make your first pod, the smallest thing Kubernetes runs: it wraps one (sometimes more) containers. Start one from nginx: <code>kubectl run hello</code> names the pod and <code>--image=nginx</code> says which image its container starts from.',g:'Send out a crew of your own: type <code>kubectl run hello --image=nginx</code>',a:[['kubectl','cmd'],['run','sub'],['hello','arg'],['--image=nginx','opt']],h:'kubectl run NAME --image=IMAGE',ans:'kubectl run hello --image=nginx',ok:c=>hasCmd(c,/^(kubectl|k) run\b/)&&K().pods.some(p=>p.name==='hello'&&p.ns==='default'&&live(p)),after:'Watch the live view: the scheduler (the part that chooses a machine) picks a worker, then the pod goes Pending → ContainerCreating → Running.'},
 {t:'Watch the crew set sail',pre:()=>K().pods.some(p=>p.name==='hello')?[]:['kubectl run hello --image=nginx'],i:'Your crew leaves its berth. List the pods in the <b>default</b> namespace, where your things go unless you say otherwise. Repeat until STATUS says Running.',g:'Watch it set sail: type <code>kubectl get pods</code>',a:[['kubectl','cmd'],['get','sub'],['pods','arg']],h:'Press ↑ to repeat it.',ans:'kubectl get pods',ok:c=>has(c,/^(kubectl|k) get (pods|pod|po)/)&&K().pods.some(p=>p.name==='hello'&&p.phase==='Running'),after:'READY 1/1 means its one container is up.'},
 {t:'Read the crew\'s log',i:'The cadet asks for the crew\'s log. <code>describe</code> shows everything about a pod (or other thing in the cluster), and at the bottom, the <b>Events</b>: what happened, in order.',g:'Read the log: type <code>kubectl describe pod hello</code>',a:[['kubectl','cmd'],['describe','sub'],['pod','arg'],['hello','arg']],h:'kubectl describe pod hello',ans:'kubectl describe pod hello',ok:c=>has(c,/^(kubectl|k) describe (pod|pods|po) hello$|^(kubectl|k) describe (pod|po)\/hello$/),after:'Scheduled → Pulling → Pulled → Started. When a pod misbehaves, these events are where you look first.'},
 {t:'Scuttle the test crew',i:'Captain Brine says the test crew is in his way. Delete the pod and watch the live view. Does anything replace it?',g:'Scuttle it: type <code>kubectl delete pod hello</code>',a:[['kubectl','cmd'],['delete','sub'],['pod','arg'],['hello','arg']],h:'kubectl delete pod hello',ans:'kubectl delete pod hello',ok:c=>hasCmd(c,/^(kubectl|k) delete (pods?|po)\b/)&&!K().pods.some(p=>p.name==='hello'&&p.ns==='default'&&live(p)),after:'It terminated and nothing took its place. A bare pod has nobody looking after it. The next chapter fixes that. Floating where it sank: the cadet\'s spyglass.'},
]},
{name:'Deployments',tier:'beginner',badge:'Lifeboat Whistle',story:'The lifeboat station keeps three crews ready and sends a new one when one goes down; scale it up and down, and find the lifeboat whistle.',view:'k8s',learned:['kubectl create deployment','--replicas','self-healing','kubectl scale','kubectl get rs'],missions:[
 {t:'Ask for three',i:'The lifeboat station keeps three crews ready and sends a new one when a crew goes down; the lifeboat whistle hangs by its door. A <b>Deployment</b> says "I want N copies (<b>replicas</b>) of this pod, always". Kubernetes then works to make it true.',g:'Ask the station for three crews: type <code>kubectl create deployment web --image=nginx:1.26 --replicas=3</code>',a:[['kubectl','cmd'],['create','sub'],['deployment','arg'],['web','arg'],['--image=nginx:1.26','opt'],['--replicas=3','opt']],h:'One line. Flags in any order.',ans:'kubectl create deployment web --image=nginx:1.26 --replicas=3',ok:c=>hasCmd(c,/^(kubectl|k) create (deployments?|deploy)\b/)&&!!Dep('web'),after:'Three pods appear in the live view, spread across both workers.'},
 {t:'Call the station roll',i:'Marlow calls the roll. List deployments. READY shows how many of the wanted pods are up.',g:'Call the roll: type <code>kubectl get deployments</code>',a:[['kubectl','cmd'],['get','sub'],['deployments','arg']],h:'deploy is a short form: kubectl get deploy',ans:'kubectl get deployments',ok:c=>has(c,/^(kubectl|k) get (deployments|deployment|deploy)/),after:'3/3 means three wanted, three ready.'},
 {t:'Where are the crews posted?',i:'Gull flies over to see where each crew took its post. <code>-o wide</code> adds the pod IP and the node.',g:'See their posts: type <code>kubectl get pods -o wide</code>',a:[['kubectl','cmd'],['get','sub'],['pods','arg'],['-o wide','opt']],h:'-o wide at the end',ans:'kubectl get pods -o wide',ok:c=>has(c,/^(kubectl|k) get (pods|pod|po) .*-o ?wide|^(kubectl|k) get (pods|po) -owide/),after:'Each pod has its own IP inside the cluster. Notice the names: web-, then a short code for the pod recipe, then a random bit.'},
 {t:'Send one crew away',pre:()=>WEBDEP(),i:'Captain Brine orders one crew away from the station: delete one of the web pods. Click a web pod in the live view to fill in its name.',g:'Dismiss one crew: type <code>kubectl delete pod web-…</code> with a real pod name',a:[['kubectl','cmd'],['delete','sub'],['pod','arg'],['web-xxxxxxxxxx-xxxxx','arg']],h:'Click any web pod on the right, then press Enter.',ans:()=>{const p=Pods('web')[0];return p?'kubectl delete pod '+p.name:'kubectl get pods'},ok:c=>S.flag.lastDeleted&&S.flag.lastDeleted.dep==='web'&&has(c,/delete/),fill:{pod:p=>`kubectl delete pod ${p.name}${p.ns!=='default'?' -n '+p.ns:''}`},after:'Watch the live view: as soon as the count dropped to 2, Kubernetes created a replacement.'},
 {t:'Spot the new crew',pre:()=>[...WEBDEP(),...(S.flag.lastDeleted?.dep==='web'?[]:[SETTLE,()=>'kubectl delete pod '+(Pods('web')[0]?.name||'web'),SETTLE])],i:'Gull points at a fresh face. List the pods again and look at the AGE column.',g:'Find the new crew: type <code>kubectl get pods</code>',a:[['kubectl','cmd'],['get','sub'],['pods','arg']],h:'kubectl get pods',ans:'kubectl get pods',ok:c=>has(c,/^(kubectl|k) get (pods|pod|po)/)&&S.flag.lastDeleted&&Pods('web').length>=3,after:'One pod is only seconds old, with a new name. That is self-healing: you describe what you want, and the cluster keeps it true.'},
 {t:'A storm is coming',pre:()=>WEBDEP(),i:'A storm is coming: ask the station for more copies.',g:'Call in five crews: type <code>kubectl scale deployment web --replicas=5</code>',a:[['kubectl','cmd'],['scale','sub'],['deployment web','arg'],['--replicas=5','opt']],h:'kubectl scale deployment web --replicas=5',ans:'kubectl scale deployment web --replicas=5',ok:c=>hasCmd(c,/^(kubectl|k) scale\b/)&&Dep('web')&&Dep('web').replicas===5,after:'Two more pods start. The scheduler puts them on the less busy worker.'},
 {t:'The storm passes',pre:()=>WEBDEP(),i:'The storm passes and the sea is quiet. Go down to 2.',g:'Send crews home: type <code>kubectl scale deployment web --replicas=2</code>',a:[['kubectl','cmd'],['scale','sub'],['deployment web','arg'],['--replicas=2','opt']],h:'Same command, smaller number.',ans:'kubectl scale deployment web --replicas=2',ok:c=>hasCmd(c,/^(kubectl|k) scale\b/)&&Dep('web')&&Dep('web').replicas===2,after:'Extra pods terminate until exactly 2 are left.'},
 {t:'The station\'s duty officer',i:'Who really keeps the crews at three? A deployment does not create pods itself. It manages a <b>ReplicaSet</b>, and the ReplicaSet keeps the pod count.',g:'Meet the duty officer: type <code>kubectl get rs</code>',a:[['kubectl','cmd'],['get','sub'],['rs','arg']],h:'rs is short for replicasets',ans:'kubectl get rs',ok:c=>has(c,/^(kubectl|k) get (rs|replicasets?)/),after:'One ReplicaSet, named after the deployment plus the template hash, the same hash that appears in each pod name. Pinned above the station door: the lifeboat whistle.'},
]},
{name:'Services',tier:'beginner',badge:'Lamp Lens',story:'Visitors need one lighthouse beam to find the crews; give them a single address and follow the beam, and find the lamp lens.',view:'k8s',setup:()=>ensureWebDep()?'(A web deployment with 3 replicas was created so this chapter has something to route to.)':'',learned:['kubectl expose','Service types','Endpoints','kubectl port-forward','labels and selectors'],missions:[
 {t:'Call three crews back',i:'Ships need one lighthouse beam to find the crews, and the lamp lens sits at the top of it. First, three web pods again, so there is traffic to spread.',g:'Call three crews back: type <code>kubectl scale deployment web --replicas=3</code>',a:[['kubectl','cmd'],['scale','sub'],['deployment web','arg'],['--replicas=3','opt']],h:'kubectl scale deployment web --replicas=3',ans:'kubectl scale deployment web --replicas=3',ok:c=>hasCmd(c,/^(kubectl|k) scale\b/)&&Dep('web')&&Dep('web').replicas===3,after:'Three pods, three different IPs. Which one should a visitor use? None of them directly.'},
 {t:'Light one beam for them all',i:'The lighthouse keeper wants one beam for every crew to follow. A <b>Service</b> is a stable name and IP in front of a changing set of pods. <code>kubectl expose</code> creates one for a deployment, and <code>--port=80</code> is the door the service opens, and unless told otherwise it sends traffic to the same port on the pods. The <b>type</b> says who can reach it: <code>NodePort</code> also opens a door on every machine in the cluster, while the default, <code>ClusterIP</code>, works only inside it.',g:'Light the beam: type <code>kubectl expose deployment web --port=80 --type=NodePort</code>',a:[['kubectl','cmd'],['expose','sub'],['deployment web','arg'],['--port=80','opt'],['--type=NodePort','opt']],h:'kubectl expose deployment web --port=80 --type=NodePort',ans:'kubectl expose deployment web --port=80 --type=NodePort',ok:c=>hasCmd(c,/^(kubectl|k) expose\b/)&&!!K().svcs['default/web'],after:'The live view draws the service above the pods it selects.'},
 {t:'Check the beams',i:'Gull checks which beams are lit. Look at TYPE, CLUSTER-IP and <code>PORT(S)</code>.',g:'Check them: type <code>kubectl get svc</code>',a:[['kubectl','cmd'],['get','sub'],['svc','arg']],h:'svc is short for services',ans:'kubectl get svc',ok:c=>has(c,/^(kubectl|k) get (svc|services?)/),after:'ClusterIP works inside the cluster. NodePort also opens a port (numbered 30000 or higher) on every node. "kubernetes" is the API server\'s own service.'},
 {t:'Who answers the beam?',i:'Which crews answer when a ship follows the beam? The service picks pods by <b>label</b> (a key=value tag stuck on a pod), and the matching pod IPs are its <b>Endpoints</b>.',g:'Ask the keeper: type <code>kubectl describe svc web</code>',a:[['kubectl','cmd'],['describe','sub'],['svc','arg'],['web','arg']],h:'kubectl describe svc web',ans:'kubectl describe svc web',ok:c=>has(c,/^(kubectl|k) describe (svc|service|services) web$|^(kubectl|k) describe (svc|service)\/web$/),after:'Selector app=web (the label it looks for), and Endpoints lists three IPs. Delete a pod and the list updates by itself.'},
 {t:'Signal the beam from shore',pre:()=>[...WEBDEP(),...SVC()],i:'You stand ashore, away from the beam. Your laptop is outside the cluster. <code>port-forward</code> opens a tunnel from a laptop port to the service. <code>svc/web</code> means "the service called web"; <code>9090:80</code> is your laptop\'s port first, then the service\'s port.',g:'Open a signal lane: type <code>kubectl port-forward svc/web 9090:80</code>',a:[['kubectl','cmd'],['port-forward','sub'],['svc/web','arg'],['9090:80','arg']],h:'Same LAPTOP:REMOTE order as docker -p.',ans:'kubectl port-forward svc/web 9090:80',ok:c=>hasCmd(c,/^(kubectl|k) port-forward\b/)&&!!K().fwd[9090],after:'Port 9090 on your laptop now leads to the web service.'},
 {t:'Watch the beam share the work',pre:()=>[...WEBDEP(),...SVC(),...FWD()],i:'Ships signal the beam one after another. Send a few requests and watch which pod answers each time. The live view flashes the one that served you.',g:'Flash the beam: type <code>curl localhost:9090</code> three times',a:[['curl','cmd'],['localhost:9090','arg']],h:'↑ and Enter to repeat.',ans:'curl localhost:9090',ok:c=>hasCmd(c,/^curl\b/)&&Object.keys(S.flag.fwdPods||{}).length>=2&&(S.flag.fwdHits||0)>=3,after:'Different pods answered. Behind one address, the work is shared. (A real port-forward sticks to one pod; we let it rotate so you can see the spreading a Service does.)'},
 {t:'The beam\'s labels',i:'The beam finds its crews by their tags. Labels are simple key=value tags. The service matches pods with <b>app=web</b>.',g:'See the crews\' labels: type <code>kubectl get pods --show-labels</code>',a:[['kubectl','cmd'],['get','sub'],['pods','arg'],['--show-labels','opt']],h:'kubectl get pods --show-labels',ans:'kubectl get pods --show-labels',ok:c=>has(c,/--show-labels/),after:'app=web links deployment, pods and service. Try `kubectl get` pods `-l` app=web to filter by label. The beam now shines through the lamp lens.'},
]},
{name:'Rolling updates',tier:'beginner',badge:'Refit Chart',story:'The fleet gets new sails one crew at a time without leaving port empty; ship a good and a broken version and roll back, and find the refit chart.',view:'k8s',setup:()=>ensureWebDep()?'(A web deployment running nginx:1.26 was created for this chapter.)':'',learned:['kubectl set image','kubectl rollout status','kubectl rollout history','ImagePullBackOff','kubectl rollout undo'],missions:[
 {t:'Refit the fleet with new sails',i:'The fleet gets new sails one crew at a time, so the harbor is never left empty; the refit chart is pinned in the refit slip. Upgrade the running site from nginx 1.26 to 1.27 with no downtime. This is a <b>rolling update</b>: Kubernetes swaps the pods a few at a time, and one such update from start to finish is a <b>rollout</b>. The container inside the deployment is called <b>nginx</b>. <code>deployment/web</code> is the deployment called web, and <code>nginx=nginx:1.27</code> means "the container called <code>nginx</code> should now run image <code>nginx:1.27</code>".',g:'Start the refit: type <code>kubectl set image deployment/web nginx=nginx:1.27</code>',a:[['kubectl','cmd'],['set image','sub'],['deployment/web','arg'],['nginx','arg'],['=nginx:1.27','val']],h:'CONTAINER=IMAGE, so nginx=nginx:1.27',ans:'kubectl set image deployment/web nginx=nginx:1.27',ok:c=>hasCmd(c,/^(kubectl|k) set image\b/)&&Dep('web')&&Dep('web').image==='nginx:1.27',after:'Watch the live view: one new pod starts, then one old pod goes, again and again.'},
 {t:'Follow the refit',i:'Marlow asks how the refit is going. Ask how the rollout is going.',g:'Check progress: type <code>kubectl rollout status deployment/web</code>',a:[['kubectl','cmd'],['rollout','sub'],['status','sub'],['deployment/web','arg']],h:'kubectl rollout status deployment/web',ans:'kubectl rollout status deployment/web',ok:c=>has(c,/^(kubectl|k) rollout status (deployment|deploy)[ /]web$/),after:'Run it again until "successfully rolled out". At every moment, at least 3 pods were serving.'},
 {t:'Read the refit log',i:'The refit chart lists every refit. Each template change is a numbered <b>revision</b>.',g:'Open the chart: type <code>kubectl rollout history deployment/web</code>',a:[['kubectl','cmd'],['rollout','sub'],['history','sub'],['deployment/web','arg']],h:'kubectl rollout history deployment/web',ans:'kubectl rollout history deployment/web',ok:c=>has(c,/^(kubectl|k) rollout history (deployment|deploy)[ /]web/),after:'Revision 1 was nginx:1.26, revision 2 is 1.27. `kubectl get` rs shows the old ReplicaSet scaled to 0, kept for rollbacks.'},
 {t:'Brine orders bad sails',i:'Captain Brine orders sails that do not exist. Deploy a version that does not exist: <b>nginx:1.99</b>.',g:'Let Brine refit: type <code>kubectl set image deployment/web nginx=nginx:1.99</code>',a:[['kubectl','cmd'],['set image','sub'],['deployment/web','arg'],['nginx=nginx:1.99','val']],h:'Same as before with 1.99.',ans:'kubectl set image deployment/web nginx=nginx:1.99',ok:c=>hasCmd(c,/^(kubectl|k) set image\b/)&&Dep('web')&&Dep('web').image==='nginx:1.99',after:'Watch the live view for a red pod.'},
 {t:'Spot the stuck crew',pre:()=>BAD_ROLLOUT(),i:'Gull squawks about a crew that cannot leave the slip. List the pods and look at STATUS.',g:'Look over the fleet: type <code>kubectl get pods</code>',a:[['kubectl','cmd'],['get','sub'],['pods','arg']],h:'kubectl get pods',ans:'kubectl get pods',ok:c=>has(c,/^(kubectl|k) get (pods|pod|po)/)&&K().pods.some(p=>/ErrImagePull|ImagePullBackOff/.test(p.phase)),after:'ErrImagePull, then ImagePullBackOff. The rollout stopped at one bad pod, and the three old pods are still serving. Nobody saw an outage.'},
 {t:'Ask the stuck crew why',pre:()=>BAD_ROLLOUT(),i:'Marlow wants the reason. Describe the broken pod. Click the red pod in the live view to fill its name.',g:'Question the crew: type <code>kubectl describe pod web-…</code> with the broken pod\'s name',a:[['kubectl','cmd'],['describe','sub'],['pod','arg'],['web-…','arg']],h:'Click the red pod on the right.',ans:()=>{const p=K().pods.find(p=>/ErrImagePull|ImagePullBackOff/.test(p.phase));return p?'kubectl describe pod '+p.name:'kubectl get pods'},ok:c=>has(c,/describe (pod|po)/)&&/Failed to pull image/.test(c.out),fill:{pod:p=>`kubectl describe pod ${p.name}${p.ns!=='default'?' -n '+p.ns:''}`},after:'The Events section says it plainly: the image was not found.'},
 {t:'Put the old sails back',pre:()=>BAD_ROLLOUT(),i:'Put the last good sails back: go back to the last good revision with one command.',g:'Undo the refit: type <code>kubectl rollout undo deployment/web</code>',a:[['kubectl','cmd'],['rollout','sub'],['undo','sub'],['deployment/web','arg']],h:'kubectl rollout undo deployment/web',ans:'kubectl rollout undo deployment/web',ok:c=>hasCmd(c,/^(kubectl|k) (rollout undo|set image)\b/)&&Dep('web')&&Dep('web').image==='nginx:1.27',after:'Back on nginx:1.27, and the red pod is cleaned up. Check `kubectl rollout` history: the good version got a new revision number. The refit chart is now yours.'},
]},
{name:'Declarative YAML',tier:'beginner',badge:'Sea Chest',story:'The harbor shop is described in one file; apply it, change it, and open the sea chest Brine locked with Marlow\'s first-crate note.',view:'k8s',files:['shop.yaml'],learned:['kubectl create namespace','kubectl apply -f','kubectl get all -n','ConfigMaps','edit, apply, repeat','kubectl delete -f'],missions:[
 {t:'A room for the shop',i:'The harbor shop is described in one file, and Captain Brine locked the sea chest away in it. <b>Namespaces</b> split one cluster into separate areas, for example per team or per app. Create one for the shop.',g:'Make the shop\'s room: type <code>kubectl create namespace shop</code>',a:[['kubectl','cmd'],['create','sub'],['namespace','arg'],['shop','arg']],h:'kubectl create namespace shop',ans:'kubectl create namespace shop',ok:c=>hasCmd(c,/^(kubectl|k) create (namespaces?|ns)\b/)&&!!K().nss.shop,after:'Names only need to be unique inside a namespace, so the shop can have its own "web" without clashing.'},
 {t:'Read the shop\'s manifest',i:'Gull flaps in with the shop\'s whole plan. So far you typed commands one by one. Real teams write the <b>desired state</b> in YAML files, called manifests. This one holds three things (Kubernetes calls each one an <b>object</b>). One of them is a <b>ConfigMap</b>, a named bundle of settings.',g:'Read the plan: type <code>cat shop.yaml</code>',a:[['cat','cmd'],['shop.yaml','arg']],h:'cat shop.yaml',ans:'cat shop.yaml',ok:c=>has(c,/^cat shop\.ya?ml$/),after:'A ConfigMap (settings), a Deployment (2 replicas, loading the ConfigMap as environment variables), and a Service. Each says which namespace it belongs to.'},
 {t:'Open the shop with one file',pre:()=>NS(),i:'One word and the whole shop opens. <code>kubectl apply -f</code> sends the whole file: <code>-f</code> names the file to read. Kubernetes creates whatever is missing.',g:'Open the shop: type <code>kubectl apply -f shop.yaml</code>',a:[['kubectl','cmd'],['apply','sub'],['-f shop.yaml','opt']],h:'kubectl apply -f shop.yaml',ans:'kubectl apply -f shop.yaml',ok:c=>hasCmd(c,/^(kubectl|k) apply\b/)&&!!Dep('shop','shop'),after:'Three objects created at once. The shop pods carry a "shop" tag in the live view.'},
 {t:'Walk through the shop',i:'Captain Brine demands a tour. <code>-n</code> picks the namespace. Without it, <code>kubectl</code> looks in "default".',g:'Tour it: type <code>kubectl get all -n shop</code>',a:[['kubectl','cmd'],['get','sub'],['all','arg'],['-n shop','opt']],h:'kubectl get all -n shop',ans:'kubectl get all -n shop',ok:c=>has(c,/^(kubectl|k) get all (-n|--namespace)[ =]shop$/),after:'Pods, service, deployment and replicaset. Try `kubectl get` all without `-n` and see they are not in default.'},
 {t:'Check the shop\'s greeting',pre:()=>SHOP_APPLIED(),i:'The shop should greet visitors. Run <code>env</code> inside a shop pod to see the ConfigMap values: it prints a program\'s environment variables. The lone <code>--</code> separates kubectl\'s own options from the command to run in the pod. Click a shop pod in the live view to fill the command.',g:'Listen at the door: type <code>kubectl exec POD -n shop -- env</code>',a:[['kubectl','cmd'],['exec','sub'],['POD','arg'],['-n shop','opt'],['--','op'],['env','cmd']],h:'Click a pod tagged shop on the right.',ans:()=>{const p=Pods('shop','shop').find(p=>p.phase==='Running');return p?`kubectl exec ${p.name} -n shop -- env`:'kubectl get pods -n shop'},ok:c=>has(c,/exec/)&&/GREETING=/.test(c.out),fill:{pod:p=>`kubectl exec ${p.name}${p.ns!=='default'?' -n '+p.ns:''} -- env`},after:'GREETING and CURRENCY came from the ConfigMap. Change settings without rebuilding the image.'},
 {t:'Staff the shop by editing its file',pre:()=>SHOP_APPLIED(),i:'A busy day: the shop needs more shopkeepers. This is the declarative way: edit the file, apply again. Change <b>replicas: 2</b> to <b>replicas: 4</b>.',g:'Hire more: type <code>edit shop.yaml</code>, change replicas to 4, save, then <code>kubectl apply -f shop.yaml</code>',a:[['edit','cmd'],['shop.yaml','arg'],['&&','op'],['kubectl apply -f shop.yaml','cmd']],h:'In the editor, find "replicas: 2" under spec. Change the number, press Save, then apply.',ans:()=>/replicas:\s*4/.test(S.files['shop.yaml']||'')?'kubectl apply -f shop.yaml':'edit shop.yaml',ok:c=>hasCmd(c,/^(kubectl|k) apply\b/)&&Dep('shop','shop')&&Dep('shop','shop').replicas===4,after:'Only the deployment said "configured". The rest was "unchanged". apply works out the difference for you.'},
 {t:'Close the shop with the same file',i:'Closing time at the harbor shop. The same file that created everything can delete everything: <code>-f</code> names the file to read, as in <code>apply</code>.',g:'Close the shop: type <code>kubectl delete -f shop.yaml</code>',a:[['kubectl','cmd'],['delete','sub'],['-f shop.yaml','opt']],h:'kubectl delete -f shop.yaml',ans:'kubectl delete -f shop.yaml',ok:c=>!Dep('shop','shop')&&has(c,/delete -f/),after:'Every object in the file is gone. You now know the full loop: write it down, apply it, change it, apply again. The shop is empty, and the sea chest Brine locked swings open at last, with Marlow\'s note from the first crate.'},
]},
];
CH.forEach((ch,i)=>{ch.pic=PICS[i]});
Object.assign(HQ,{ensureFiles,CH});
})(window.HQ = window.HQ || {});
